area-name.mjs.text:
// Display names for area rows. Preset space types already have a label; an
// "Other space" row does not, and a bid that lists three identical "Area N"
// lines is not something a contractor can paste into a proposal. A trimmed
// custom name wins, then the preset label, then a stable fallback.

export function displayAreaName(presetLabel, customName, index) {
  const custom = String(customName ?? '').trim();
  if (custom) return custom;
  const preset = String(presetLabel ?? '').trim();
  if (preset) return preset;
  return `Area ${index + 1}`;
}

// Optional proposal names work on every row, including catalog types, so two
// restrooms can be told apart. Draft restore keeps space type in its own
// field; the typed name is only a label.
export function nameForRow(presetLabel, customName, index) {
  return displayAreaName(presetLabel, customName, index);
}

// Area names are written into the labor-split HTML. Escape so a name like
// "Hall <west>" cannot inject markup into the contractor's own page.
export function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

calc.mjs.text:
import { displayAreaName } from './area-name.mjs';

// Pure bid arithmetic for a commercial cleaning (janitorial) contract. No
// network, no state: every rate, wage, and production figure is an input, so
// the result stays a transparent calculation the contractor can check against
// their own payroll and supply invoices rather than a claim about what any
// building "should" cost.
//
// The method is the one the trade actually bids with: cleanable square feet
// divided by a production rate (square feet one cleaner covers per hour) gives
// labor hours, and every other cost is layered on top of those hours. That is
// what separates a defensible bid from a square-foot guess — a building that
// is 15% restrooms takes far more labor per square foot than one that is all
// open office, and a flat price-per-square-foot rule cannot see the difference.

// Weeks per month, averaged (52 / 12). Cleaning contracts are priced monthly
// but scheduled weekly, so the conversion has to be the average rather than a
// flat 4 — using 4 understates monthly hours by about 8%, which is more than
// the typical profit margin on a janitorial contract.
export const WEEKS_PER_MONTH = 52 / 12;

// Common starting points for production rates, in cleanable square feet per
// cleaner-hour, for a full service clean of that space type. These are
// ballpark figures to start from, NOT an industry standard or a guarantee:
// real rates depend on crew, equipment, layout, congestion, and how much is
// actually done on each visit. Contractors should replace them with rates
// timed from their own crews.
export const PRODUCTION_RATE_PRESETS = Object.freeze([
  { label: 'Open office / cubicles', rate: 4000 },
  { label: 'Private offices', rate: 3000 },
  { label: 'Lobby & corridors', rate: 5000 },
  { label: 'Restrooms (full clean)', rate: 1200 },
  { label: 'Break room / kitchen', rate: 2000 },
  { label: 'Classrooms', rate: 2500 },
  { label: 'Medical exam rooms', rate: 1000 },
  { label: 'Retail sales floor', rate: 5000 },
  { label: 'Warehouse (auto-scrub)', rate: 12000 },
  { label: 'Stairwells', rate: 1500 },
]);

// One-time project work that rides on the same bid — initial cleans, strip
// and wax, carpet extraction. Rates are ballpark starter figures in cleanable
// square feet per cleaner-hour, NOT a standard or a quote. "Passes" is coats
// of finish or extra machine passes; hours = square feet ÷ rate × passes.
export const PROJECT_RATE_PRESETS = Object.freeze([
  { label: 'Strip & wax (VCT)', rate: 250, passes: 2 },
  { label: 'Carpet extraction', rate: 300, passes: 1 },
  { label: 'Initial deep clean', rate: 1500, passes: 1 },
  { label: 'Post-construction clean', rate: 800, passes: 1 },
  { label: 'Hard-floor machine scrub', rate: 2000, passes: 1 },
]);

// Common day-porter / attendant roles. These are priced as scheduled shifts,
// not production rates — the customer is buying a person on site during
// business hours, not a cleaned square-foot count.
export const SHIFT_ROLE_PRESETS = Object.freeze([
  { label: 'Day porter / lobby attendant' },
  { label: 'Restroom attendant' },
  { label: 'Floor walker / floater' },
  { label: 'After-hours supervisor' },
  { label: 'Mailroom / dock attendant' },
]);

function number(value, name, { min = 0, allowZero = true } = {}) {
  const result = Number(value);
  if (!Number.isFinite(result)) throw new Error(`${name} must be a number`);
  if (result < min) throw new Error(`${name} must be at least ${min}`);
  if (!allowZero && result === 0) throw new Error(`${name} must be greater than zero`);
  return result;
}

/**
 * Price a recurring janitorial contract from its areas and cost structure.
 *
 * @param {object} input
 * @param {Array<{name?: string, squareFeet: number, productionRate: number, cleaningsPerWeek: number}>} input.areas
 *   One row per distinct space type. Splitting the building this way is the
 *   whole point: a single blended rate hides the restroom labor that sinks
 *   underpriced bids. May be empty when the contract is shift-only.
 * @param {Array<{name?: string, people: number, hoursPerShift: number, shiftsPerWeek: number, hourlyWage?: number|string}>} [input.shifts]
 *   Optional day-porter / attendant rows. Priced as scheduled headcount, not
 *   square feet: people × hours × shifts/week × 52/12. An omitted hourly
 *   wage uses the contract cleaner wage.
 * @param {number} [input.crewSize]         Cleaners available on each night-clean visit.
 * @param {number} [input.shiftHours]       Hours available per cleaner on that visit.
 * @param {number} [input.availableHoursPerCleaner] Alias for shiftHours used by the form.
 * @param {number} input.hourlyWage         What the cleaner is paid per hour.
 * @param {number} input.burdenRate         Payroll burden as a % on top of wage
 *   (employer taxes, workers' compensation, insurance, paid time off).
 * @param {number} input.suppliesPerSqFtMonth  Consumables and chemicals, per
 *   cleanable square foot per month.
 * @param {number} input.equipmentMonthly   Equipment, vehicle, and travel cost per month.
 * @param {number} input.otherMonthly       Anything else billed to this job monthly.
 * @param {number} input.overheadRate       Business overhead as a % on direct cost.
 * @param {number} input.targetMargin       Net profit as a % of the final price.
 * @param {number|null} [input.minimumMonthlyPrice] Optional floor for small or
 *   inconvenient accounts. The target-margin price is used when it is higher.
 * @param {Array<{name?: string, squareFeet: number, productionRate: number, passes?: number, materials?: number}>} [input.projects]
 *   Optional one-time work (strip and wax, extraction, initial clean). Priced
 *   with the same loaded wage, overhead, and margin as the monthly contract,
 *   but invoiced once — not rolled into the recurring price.
 * @param {Array<{name?: string, costPerOccurrence: number, occurrencesPerYear: number}>} [input.periodicServices]
 *   Recurring lump work (quarterly floor care, twice-yearly extraction)
 *   priced as cost × visits/year, then averaged into the monthly contract.
 *   Distinct from `projects`, which are production-rate jobs invoiced once.
 * @param {number|null} input.proposedPrice Optional: a price already on the
 *   table, so the contractor can see the margin it actually leaves.
 */
export function calculateBid(input) {
  const areasInput = Array.isArray(input.areas) ? input.areas : [];
  const shiftsInput = Array.isArray(input.shifts) ? input.shifts : [];
  if (areasInput.length === 0 && shiftsInput.length === 0) {
    throw new Error('Add at least one area or day-porter shift to price');
  }

  const hourlyWage = number(input.hourlyWage ?? 0, 'Hourly wage');
  const burdenRate = number(input.burdenRate ?? 0, 'Payroll burden');
  const suppliesPerSqFtMonth = number(input.suppliesPerSqFtMonth ?? 0, 'Supplies per sq ft');
  const equipmentMonthly = number(input.equipmentMonthly ?? 0, 'Equipment cost');
  const otherMonthly = number(input.otherMonthly ?? 0, 'Other monthly cost');
  const overheadRate = number(input.overheadRate ?? 0, 'Overhead');
  const targetMargin = number(input.targetMargin ?? 0, 'Target margin');
  const crewSize = number(input.crewSize ?? 1, 'Crew size', { allowZero: false });
  const shiftHours = number(
    input.availableHoursPerCleaner ?? input.shiftHours ?? 4,
    'Available hours per cleaner',
    { allowZero: false },
  );
  if (!Number.isInteger(crewSize)) throw new Error('Crew size must be a whole number');
  if (targetMargin >= 100) throw new Error('Target margin must be less than 100%');

  const hasMinimumPrice = input.minimumMonthlyPrice !== null
    && input.minimumMonthlyPrice !== undefined
    && input.minimumMonthlyPrice !== '';
  const minimumMonthlyPrice = hasMinimumPrice
    ? number(input.minimumMonthlyPrice, 'Minimum monthly price')
    : null;

  const loadedWage = hourlyWage * (1 + burdenRate / 100);

  const areas = areasInput.map((area, index) => {
    const label = displayAreaName('', area.name, index);
    const squareFeet = number(area.squareFeet ?? 0, `${label}: cleanable square feet`);
    // A zero production rate would divide by zero and report a free clean, so
    // it is rejected rather than defaulted — the contractor has to state how
    // fast the space actually cleans.
    const productionRate = number(area.productionRate ?? 0, `${label}: production rate`, { allowZero: false });
    const cleaningsPerWeek = number(area.cleaningsPerWeek ?? 0, `${label}: cleanings per week`);
    const hoursPerCleaning = squareFeet / productionRate;
    const monthlyHours = hoursPerCleaning * cleaningsPerWeek * WEEKS_PER_MONTH;
    return {
      name: label,
      squareFeet,
      productionRate,
      cleaningsPerWeek,
      hoursPerCleaning,
      monthlyHours,
      monthlyLaborCost: monthlyHours * loadedWage,
    };
  });

  const shifts = shiftsInput.map((shift, index) => {
    const label = shift.name?.trim() || `Shift ${index + 1}`;
    const people = number(shift.people ?? 0, `${label}: people`);
    const hoursPerShift = number(shift.hoursPerShift ?? 0, `${label}: hours per shift`);
    const shiftsPerWeek = number(shift.shiftsPerWeek ?? 0, `${label}: shifts per week`);
    const hasOwnWage = shift.hourlyWage !== null && shift.hourlyWage !== undefined && shift.hourlyWage !== '';
    const shiftWage = hasOwnWage ? number(shift.hourlyWage, `${label}: hourly wage`) : hourlyWage;
    const shiftLoadedWage = shiftWage * (1 + burdenRate / 100);
    // The customer is buying coverage, not a production rate: one person on
    // an 8-hour weekday shift is 8 × 5 × 52/12 hours a month, whether they
    // spend that time on restrooms, trash, or standing in the lobby.
    const monthlyHours = people * hoursPerShift * shiftsPerWeek * WEEKS_PER_MONTH;
    return {
      name: label,
      people,
      hoursPerShift,
      shiftsPerWeek,
      hourlyWage: shiftWage,
      loadedWage: shiftLoadedWage,
      monthlyHours,
      monthlyLaborCost: monthlyHours * shiftLoadedWage,
    };
  });

  const totalSquareFeet = areas.reduce((sum, a) => sum + a.squareFeet, 0);
  const areaMonthlyHours = areas.reduce((sum, a) => sum + a.monthlyHours, 0);
  const shiftMonthlyHours = shifts.reduce((sum, s) => sum + s.monthlyHours, 0);
  const monthlyHours = areaMonthlyHours + shiftMonthlyHours;
  const areaMonthlyLaborCost = areaMonthlyHours * loadedWage;
  const shiftMonthlyLaborCost = shifts.reduce((sum, s) => sum + s.monthlyLaborCost, 0);
  const monthlyLaborCost = areaMonthlyLaborCost + shiftMonthlyLaborCost;
  const monthlySupplies = totalSquareFeet * suppliesPerSqFtMonth;

  const periodicServices = (Array.isArray(input.periodicServices) ? input.periodicServices : []).map((service, index) => {
    const name = service.name?.trim() || `Periodic service ${index + 1}`;
    const costPerOccurrence = number(service.costPerOccurrence ?? 0, `${name}: cost per occurrence`);
    const occurrencesPerYear = number(service.occurrencesPerYear ?? 0, `${name}: occurrences per year`);
    return {
      name,
      costPerOccurrence,
      occurrencesPerYear,
      annualCost: costPerOccurrence * occurrencesPerYear,
    };
  });
  const annualPeriodicCost = periodicServices.reduce((sum, service) => sum + service.annualCost, 0);
  const monthlyPeriodicCost = annualPeriodicCost / 12;

  // Overhead is a markup on the direct cost of servicing this job, which is
  // how a small contractor recovers office, admin, and sales cost. It is
  // deliberately not applied to itself or to profit.
  const directCost = monthlyLaborCost + monthlySupplies + equipmentMonthly + otherMonthly + monthlyPeriodicCost;
  const monthlyOverhead = directCost * overheadRate / 100;
  const monthlyCost = directCost + monthlyOverhead;

  // Margin is a share of price, not a markup on cost, because that is how the
  // customer's number is quoted and how the contractor's P&L reads it.
  const targetMarginPrice = monthlyCost / (1 - targetMargin / 100);
  const monthlyPrice = minimumMonthlyPrice === null
    ? targetMarginPrice
    : Math.max(targetMarginPrice, minimumMonthlyPrice);
  const monthlyProfit = monthlyPrice - monthlyCost;

  const hasProposed = input.proposedPrice !== null && input.proposedPrice !== undefined && input.proposedPrice !== '';
  const proposedPrice = hasProposed ? number(input.proposedPrice, 'Price you are considering') : null;

  const projectsInput = Array.isArray(input.projects) ? input.projects : [];
  const projects = projectsInput.map((project, index) => {
    const label = project.name?.trim() || `Project ${index + 1}`;
    const squareFeet = number(project.squareFeet ?? 0, `${label}: project square feet`);
    const productionRate = number(project.productionRate ?? 0, `${label}: project production rate`, { allowZero: false });
    const passes = number(project.passes ?? 1, `${label}: passes`, { min: 0 });
    const materials = number(project.materials ?? 0, `${label}: project materials`);
    const hours = productionRate === 0 ? 0 : (squareFeet / productionRate) * passes;
    const laborCost = hours * loadedWage;
    const directCost = laborCost + materials;
    const overhead = directCost * overheadRate / 100;
    const cost = directCost + overhead;
    const price = cost / (1 - targetMargin / 100);
    return {
      name: label,
      squareFeet,
      productionRate,
      passes,
      hours,
      laborCost,
      materials,
      overhead,
      cost,
      price,
      profit: price - cost,
    };
  });

  const projectHours = projects.reduce((sum, project) => sum + project.hours, 0);
  const projectLaborCost = projects.reduce((sum, project) => sum + project.laborCost, 0);
  const projectMaterials = projects.reduce((sum, project) => sum + project.materials, 0);
  const projectOverhead = projects.reduce((sum, project) => sum + project.overhead, 0);
  const projectCost = projects.reduce((sum, project) => sum + project.cost, 0);
  const projectPrice = projects.reduce((sum, project) => sum + project.price, 0);
  const projectProfit = projectPrice - projectCost;
  const share = hours => (monthlyHours === 0 ? 0 : hours / monthlyHours * 100);
  const hoursPerVisitTotal = areas.reduce((sum, a) => sum + (a.cleaningsPerWeek > 0 ? a.hoursPerCleaning : 0), 0);
  const visitCapacityHours = crewSize * shiftHours;
  const visitUtilization = hoursPerVisitTotal === 0 || visitCapacityHours === 0
    ? 0
    : hoursPerVisitTotal / visitCapacityHours * 100;

  return {
    areas: areas.map(area => ({
      ...area,
      // Share of total labor hours (production + shifts). This is the line
      // that shows a contractor that 8% of the floor area is eating 30% of
      // the labor — and that a day porter can dwarf both.
      hoursShare: share(area.monthlyHours),
    })),
    shifts: shifts.map(shift => ({
      ...shift,
      hoursShare: share(shift.monthlyHours),
    })),
    totalSquareFeet,
    loadedWage,
    hoursPerVisitTotal,
    crewSize,
    shiftHours,
    visitCapacityHours,
    visitUtilization,
    visitOverCapacity: hoursPerVisitTotal > visitCapacityHours,
    areaMonthlyHours,
    shiftMonthlyHours,
    monthlyHours,
    areaMonthlyLaborCost,
    shiftMonthlyLaborCost,
    monthlyLaborCost,
    monthlySupplies,
    equipmentMonthly,
    otherMonthly,
    monthlyOverhead,
    monthlyCost,
    targetMarginPrice,
    minimumMonthlyPrice,
    minimumPriceApplied: minimumMonthlyPrice !== null && minimumMonthlyPrice > targetMarginPrice,
    monthlyPrice,
    monthlyProfit,
    annualPrice: monthlyPrice * 12,
    // The two sanity numbers a contractor checks a bid against before sending
    // it: what it works out to per square foot, and what they are effectively
    // billing per labor hour.
    pricePerSqFtMonth: totalSquareFeet === 0 ? null : monthlyPrice / totalSquareFeet,
    effectiveHourlyRate: monthlyHours === 0 ? null : monthlyPrice / monthlyHours,
    // Price at which the job stops making money — the walk-away number to hold
    // in mind when a prospect asks them to sharpen their pencil.
    breakEvenMonthlyPrice: monthlyCost,
    proposed: proposedPrice === null ? null : {
      price: proposedPrice,
      profit: proposedPrice - monthlyCost,
      margin: proposedPrice === 0 ? 0 : (proposedPrice - monthlyCost) / proposedPrice * 100,
      hourlyRate: monthlyHours === 0 ? null : proposedPrice / monthlyHours,
      // A bid below break-even is the failure this tool exists to catch.
      belowBreakEven: proposedPrice < monthlyCost,
    },
    periodicServices,
    monthlyPeriodicCost,
    annualPeriodicCost,
    hasPeriodicWork: annualPeriodicCost > 0,
    projects,
    projectHours,
    projectLaborCost,
    projectMaterials,
    projectOverhead,
    projectCost,
    projectPrice,
    projectProfit,
    // One-time work is invoiced with the first month, not amortized into the
    // recurring price — mixing them is how a contractor underprices the
    // contract for the remaining eleven months.
    firstMonthInvoice: monthlyPrice + projectPrice,
    breakEvenFirstMonth: monthlyCost + projectCost,
    hasProjectWork: projectHours > 0 || projectMaterials > 0,
  };
}

function money(value) {
  const format = (value) => `$${value.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  const text = format(Math.abs(value));
  return value < 0 && /[1-9]/.test(text) ? `-${text}` : text;
}

/**
 * Plain-text bid draft a contractor can paste into a proposal. One-time
 * project work is listed separately from the monthly contract so the first
 * invoice is not mistaken for the recurring price.
 */
export function formatBidSummary(result) {
  const spaces = result.areas
    .filter(area => area.squareFeet > 0 && area.cleaningsPerWeek > 0)
    .map(area => `- ${area.name}: ${area.squareFeet.toLocaleString('en-US')} sq ft, ${area.cleaningsPerWeek}x/week`)
    .join('\n');
  const porterLines = (result.shifts || [])
    .filter(shift => shift.monthlyHours > 0)
    .map(shift => `- ${shift.name}: ${shift.people} × ${shift.hoursPerShift} h × ${shift.shiftsPerWeek}/week (${shift.monthlyHours.toFixed(1)} h/month)`)
    .join('\n');
  const porterBlock = porterLines
    ? [
        '',
        'DAY PORTER / SCHEDULED SHIFTS',
        porterLines,
        `Day-porter hours per month: ${result.shiftMonthlyHours.toFixed(1)}`,
      ]
    : [];
  const projectLines = (result.projects || [])
    .filter(project => project.squareFeet > 0 || project.materials > 0)
    .map(project => `- ${project.name}: ${project.squareFeet.toLocaleString('en-US')} sq ft, ${project.passes} pass${project.passes === 1 ? '' : 'es'}, ${project.hours.toFixed(1)} h — ${money(project.price)}`)
    .join('\n');
  const projectBlock = result.hasProjectWork
    ? [
        '',
        'ONE-TIME PROJECT WORK',
        projectLines || '- No project rows entered',
        `One-time project total: ${money(result.projectPrice)}`,
        `First-month invoice (monthly + project): ${money(result.firstMonthInvoice)}`,
      ]
    : [];
  const periodicLines = (result.periodicServices || [])
    .filter(service => service.annualCost > 0)
    .map(service => `- ${service.name}: ${money(service.costPerOccurrence)} × ${service.occurrencesPerYear}/year (${money(service.annualCost / 12)}/month)`)
    .join('\n');
  const periodicBlock = result.hasPeriodicWork
    ? [
        '',
        'PERIODIC SERVICES (MONTHLY AVERAGE)',
        periodicLines || '- No periodic rows entered',
        `Periodic work in the monthly: ${money(result.monthlyPeriodicCost)}`,
      ]
    : [];
  return [
    'COMMERCIAL CLEANING BID',
    '',
    `Proposed monthly service: ${money(result.monthlyPrice)}`,
    ...(result.minimumPriceApplied ? [`Minimum charge floor applied: ${money(result.minimumMonthlyPrice)}`] : []),
    `Annual contract value: ${money(result.annualPrice)}`,
    `Service labor: ${result.monthlyHours.toFixed(1)} hours/month`,
    `Price per square foot: $${result.pricePerSqFtMonth === null ? 'n/a' : result.pricePerSqFtMonth.toFixed(3)}/sq ft/month`,
    ...porterBlock,
    ...projectBlock,
    ...periodicBlock,
    '',
    'SERVICE AREAS',
    spaces || '- No service areas entered',
    '',
    `Scope basis: ${result.hoursPerVisitTotal.toFixed(2)} labor hours per visit at the entered frequencies.`,
    `Crew capacity: ${result.crewSize} cleaner(s) × ${result.shiftHours.toFixed(2)} hours = ${result.visitCapacityHours.toFixed(2)} hours per visit (${result.visitUtilization.toFixed(0)}% used).`,
    'This is a draft for review. Confirm scope, schedule, insurance, taxes, and all pricing before sending.',
  ].join('\n');
}

/**
 * Compare a building-wide frequency cut (or increase) against a linear
 * discount of the current monthly price.
 *
 * Prospects routinely ask for 3×/week instead of 5× and offer 60% of the
 * current price. Labor hours do scale with visits. In this model, supplies
 * are a monthly-per-square-foot line, and equipment/travel stay on the job
 * regardless of how many days you show up — so a 40% cut in days is not a
 * 40% cut in cost. Accepting the linear number silently eats the margin
 * the original bid was built on.
 *
 * Each area's own weekly frequency is scaled so a mixed schedule (restrooms
 * 5×, offices 3×) stays proportional. The building-level currentWeekly is
 * the cadence the comparison is about: if the area rows still say 3× while
 * the contractor typed 5× as today's building week, baseline labor follows
 * the 5× cut, not a mix of the two.
 *
 * @param {object} input                 Same shape as calculateBid.
 * @param {object} options
 * @param {number} options.currentWeekly How many days a week the building is
 *   currently cleaned — the number the contractor quotes, not a per-area max.
 * @param {number} options.proposedWeekly The schedule the prospect is asking for.
 * @param {number|string|null} [options.clientOfferMonthly] Optional price they
 *   put on the reduced schedule, scored against the reduced cost base.
 */
export function compareFrequencyReduction(input, options = {}) {
  const currentWeekly = number(options.currentWeekly ?? 0, 'Current cleanings per week', { allowZero: false });
  const proposedWeekly = number(options.proposedWeekly ?? 0, 'Proposed cleanings per week');
  const factor = proposedWeekly / currentWeekly;

  const areas = Array.isArray(input.areas) ? input.areas : [];
  const areaFreqs = areas.map((area, index) => {
    const label = area.name?.trim() || `Area ${index + 1}`;
    return number(area.cleaningsPerWeek ?? 0, `${label}: cleanings per week`);
  });
  // Highest scheduled area is the building week the rows already encode.
  // Rebase onto currentWeekly when that disagrees, so a 5→3 comparison is
  // actually priced at 5 days then 3 days rather than 3 days then 1.8.
  const typicalAreaWeek = Math.max(0, ...areaFreqs);
  const alignFactor = typicalAreaWeek > 0 ? currentWeekly / typicalAreaWeek : 1;

  const alignedAreas = areas.map((area, index) => ({
    ...area,
    cleaningsPerWeek: areaFreqs[index] * alignFactor,
  }));
  const scaledAreas = alignedAreas.map((area, index) => ({
    ...area,
    cleaningsPerWeek: areaFreqs[index] * alignFactor * factor,
  }));

  const baseline = calculateBid({ ...input, areas: alignedAreas, proposedPrice: undefined });
  const reduced = calculateBid({
    ...input,
    areas: scaledAreas,
    proposedPrice: options.clientOfferMonthly,
  });

  const naiveLinearPrice = baseline.monthlyPrice * factor;
  const naiveProfit = naiveLinearPrice - reduced.monthlyCost;
  const naiveMargin = naiveLinearPrice === 0 ? 0 : naiveProfit / naiveLinearPrice * 100;
  const leftOnTable = reduced.monthlyPrice - naiveLinearPrice;

  return {
    currentWeekly,
    proposedWeekly,
    reductionFactor: factor,
    baseline,
    reduced,
    naiveLinearPrice,
    naiveProfit,
    naiveMargin,
    naiveBelowBreakEven: naiveLinearPrice < reduced.monthlyCost,
    priceToHoldTargetMargin: reduced.monthlyPrice,
    walkAwayAtReduced: reduced.breakEvenMonthlyPrice,
    leftOnTable,
    laborHoursDropped: baseline.monthlyHours - reduced.monthlyHours,
    laborCostDropped: baseline.monthlyLaborCost - reduced.monthlyLaborCost,
    unscaledMonthly: baseline.monthlySupplies + baseline.equipmentMonthly + baseline.otherMonthly,
    // A day porter is scheduled against the building's own week, not against
    // the cleaning cadence, so their wages are the largest thing that does
    // *not* fall when visits are cut — often several times the supplies and
    // equipment combined. Reported separately so the page can say so rather
    // than leaving it inside a labour figure the reader takes for scaling.
    unscaledShiftLabor: baseline.shiftMonthlyLaborCost,
    suppliesUnchanged: Math.abs(reduced.monthlySupplies - baseline.monthlySupplies) < 1e-9,
    equipmentUnchanged: Math.abs(reduced.equipmentMonthly - baseline.equipmentMonthly) < 1e-9,
    clientOffer: reduced.proposed,
  };
}

/**
 * One paragraph a contractor can paste into a renewal reply. Arithmetic only —
 * it does not tell them to accept or refuse.
 */
export function frequencyReductionNote(comparison, { targetMargin } = {}) {
  const money = (value) => {
    const format = (value) => `$${value.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    const text = format(Math.abs(value));
    return value < 0 && /[1-9]/.test(text) ? `-${text}` : text;
  };
  const pct = comparison.reductionFactor * 100;
  const marginPct = Number.isFinite(targetMargin) ? targetMargin : 20;
  const direction = comparison.proposedWeekly < comparison.currentWeekly ? 'cut' : 'change';
  const naiveLine = comparison.naiveBelowBreakEven
    ? `Accepting ${pct.toFixed(0)}% of the ${comparison.currentWeekly}× price (${money(comparison.naiveLinearPrice)}) would lose ${money(Math.abs(comparison.naiveProfit))} a month against the ${comparison.proposedWeekly}× cost base. Walk-away on the reduced schedule is ${money(comparison.walkAwayAtReduced)}.`
    : `A linear ${pct.toFixed(0)}% of the ${comparison.currentWeekly}× price is ${money(comparison.naiveLinearPrice)}, which leaves a ${comparison.naiveMargin.toFixed(1)}% margin at ${comparison.proposedWeekly}× — ${money(Math.abs(comparison.leftOnTable))} a month ${comparison.leftOnTable > 0 ? 'below' : 'above'} the price that holds a ${marginPct}% target.`;
  return [
    `At ${comparison.proposedWeekly}×/week the monthly price that still holds a ${marginPct}% margin is ${money(comparison.priceToHoldTargetMargin)}, not a linear ${direction} of the ${comparison.currentWeekly}× price (${money(comparison.baseline.monthlyPrice)}).`,
    `Labor drops with the visits (${comparison.baseline.monthlyHours.toFixed(1)} h → ${comparison.reduced.monthlyHours.toFixed(1)} h). Supplies, equipment, and travel stay on the job (${money(comparison.unscaledMonthly)}/month in this bid).${comparison.unscaledShiftLabor > 0 ? ` Scheduled shift labor stays too — ${money(comparison.unscaledShiftLabor)}/month of day-porter wages are not part of that drop.` : ''}`,
    naiveLine,
  ].join(' ');
}

/**
 * Compare who buys restroom paper, soap, and liners.
 *
 * Prospects routinely say "we'll buy the paper if you drop the supplies
 * line." Restroom stock is only a share of that line — chemicals, finish,
 * and glass stay yours. Dropping the whole line from today's price silently
 * eats the chemicals and the markup on them. And if they run out, the
 * emergency fill you still make is less efficient than stocking it yourself,
 * so the price that holds your margin can land *above* the you-supply bid.
 *
 * Labor, equipment, and travel do not change. Only the supplies (and the
 * optional emergency-fill) line moves, then overhead and margin are reapplied.
 *
 * @param {object} input  Same shape as calculateBid.
 * @param {object} options
 * @param {number} [options.restroomSharePercent=65] Share of the monthly
 *   supplies line that is paper, soap, liners, and seat covers.
 * @param {number} [options.emergencyFillMonthly=0] Extra monthly cost when
 *   they "buy it" but you still restock after they run out.
 * @param {number|string|null} [options.clientOfferMonthly] Optional price
 *   they put on the labor-only / drop-supplies ask, scored against each
 *   reduced cost base.
 */
export function compareSupplyResponsibility(input, options = {}) {
  const restroomSharePercent = number(
    options.restroomSharePercent ?? 65,
    'Restroom stock share of supplies',
  );
  if (restroomSharePercent > 100) {
    throw new Error('Restroom stock share of supplies must be at most 100');
  }
  const emergencyFillMonthly = number(
    options.emergencyFillMonthly ?? 0,
    'Emergency fill when they run out',
  );
  const suppliesRate = number(input.suppliesPerSqFtMonth ?? 0, 'Supplies per sq ft');
  const otherMonthly = number(input.otherMonthly ?? 0, 'Other monthly cost');
  const overheadRate = number(input.overheadRate ?? 0, 'Overhead');
  const targetMargin = number(input.targetMargin ?? 0, 'Target margin');
  if (targetMargin >= 100) throw new Error('Target margin must be less than 100%');

  const restroomShare = restroomSharePercent / 100;
  const chemicalRate = suppliesRate * (1 - restroomShare);
  const bidInput = { ...input, proposedPrice: undefined };

  const youSupply = calculateBid(bidInput);
  const theyBuyRestroom = calculateBid({
    ...bidInput,
    suppliesPerSqFtMonth: chemicalRate,
    proposedPrice: options.clientOfferMonthly,
  });
  const theyBuyAll = calculateBid({
    ...bidInput,
    suppliesPerSqFtMonth: 0,
    proposedPrice: options.clientOfferMonthly,
  });
  const theyBuyButYouFill = calculateBid({
    ...bidInput,
    suppliesPerSqFtMonth: chemicalRate,
    otherMonthly: otherMonthly + emergencyFillMonthly,
    proposedPrice: options.clientOfferMonthly,
  });

  // The verbal ask is "take the supplies off the bid" — today's price minus
  // the fully marked-up supplies line, as if chemicals vanished too.
  const suppliesInPrice = youSupply.monthlySupplies * (1 + overheadRate / 100) / (1 - targetMargin / 100);
  const naiveDropPrice = youSupply.monthlyPrice - suppliesInPrice;
  const naiveProfitAtRestroom = naiveDropPrice - theyBuyRestroom.monthlyCost;
  const naiveMarginAtRestroom = naiveDropPrice === 0 ? 0 : naiveProfitAtRestroom / naiveDropPrice * 100;
  const naiveProfitAtFill = naiveDropPrice - theyBuyButYouFill.monthlyCost;
  const naiveMarginAtFill = naiveDropPrice === 0 ? 0 : naiveProfitAtFill / naiveDropPrice * 100;

  return {
    restroomSharePercent,
    emergencyFillMonthly,
    restroomSuppliesMonthly: youSupply.monthlySupplies * restroomShare,
    chemicalSuppliesMonthly: youSupply.monthlySupplies * (1 - restroomShare),
    youSupply,
    theyBuyRestroom,
    theyBuyAll,
    theyBuyButYouFill,
    suppliesInPrice,
    naiveDropPrice,
    naiveProfitAtRestroom,
    naiveMarginAtRestroom,
    naiveBelowBreakEvenAtRestroom: naiveDropPrice < theyBuyRestroom.monthlyCost,
    naiveProfitAtFill,
    naiveMarginAtFill,
    naiveBelowBreakEvenAtFill: naiveDropPrice < theyBuyButYouFill.monthlyCost,
    leftoverIfTheyBuyRestroom: youSupply.monthlyPrice - theyBuyRestroom.monthlyPrice,
    leftoverIfTheyBuyAll: youSupply.monthlyPrice - theyBuyAll.monthlyPrice,
    fillPremiumVsYouSupply: theyBuyButYouFill.monthlyPrice - youSupply.monthlyPrice,
    fillCostsMoreThanYouSupply: theyBuyButYouFill.monthlyPrice > youSupply.monthlyPrice,
    clientOfferRestroom: theyBuyRestroom.proposed,
    clientOfferAll: theyBuyAll.proposed,
    clientOfferFill: theyBuyButYouFill.proposed,
  };
}

/**
 * One paragraph a contractor can paste into a "we'll buy the paper" reply.
 * Arithmetic only — it does not tell them to accept or refuse.
 */
export function supplyResponsibilityNote(comparison, { targetMargin } = {}) {
  const money = (value) => {
    const format = (value) => `$${value.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    const text = format(Math.abs(value));
    return value < 0 && /[1-9]/.test(text) ? `-${text}` : text;
  };
  const marginPct = Number.isFinite(targetMargin) ? targetMargin : 20;
  const restroomLine = `Restroom paper, soap, and liners are ${comparison.restroomSharePercent.toFixed(0)}% of this supplies line (${money(comparison.restroomSuppliesMonthly)}); chemicals, finish, and glass stay yours (${money(comparison.chemicalSuppliesMonthly)}).`;
  const honestLine = `If they take only the restroom stock, the monthly price that still holds a ${marginPct}% margin is ${money(comparison.theyBuyRestroom.monthlyPrice)}, not today's ${money(comparison.youSupply.monthlyPrice)} minus the whole supplies line (${money(comparison.naiveDropPrice)}).`;
  const fillLine = comparison.emergencyFillMonthly > 0
    ? (comparison.fillCostsMoreThanYouSupply
      ? `If you still emergency-fill when they run out (${money(comparison.emergencyFillMonthly)}/month), the price that holds the margin is ${money(comparison.theyBuyButYouFill.monthlyPrice)} — ${money(comparison.fillPremiumVsYouSupply)} a month above you-supplying.`
      : `If you still emergency-fill when they run out (${money(comparison.emergencyFillMonthly)}/month), the price that holds the margin is ${money(comparison.theyBuyButYouFill.monthlyPrice)}.`)
    : `Labor, equipment, and travel do not move when they take the paper.`;
  const naiveLine = comparison.naiveBelowBreakEvenAtFill || comparison.naiveBelowBreakEvenAtRestroom
    ? `Dropping the whole supplies line from today's price (${money(comparison.naiveDropPrice)}) would lose ${money(Math.abs(comparison.naiveBelowBreakEvenAtFill ? comparison.naiveProfitAtFill : comparison.naiveProfitAtRestroom))} a month against the cost you still carry.`
    : `Dropping the whole supplies line from today's price leaves a ${comparison.naiveMarginAtRestroom.toFixed(1)}% margin if they actually take the restroom stock, versus the ${marginPct}% the original bid was built on.`;
  return [restroomLine, honestLine, fillLine, naiveLine].join(' ');
}

/**
 * Compare quoting the takeover / initial clean as a one-time line versus
 * throwing it into month 1 at today's monthly.
 *
 * A neglected or vacant building's first visit is several regular cleans of
 * labor plus extra chemicals. Prospects ask to "just include it." Month 1
 * then carries a project on a periodic price. If they cancel after 30 days,
 * that giveaway is the whole relationship. This is not strip-and-wax (a
 * recurring floor-finish project) and not a second address — it is the
 * one-time deep clean that wins the monthly.
 *
 * Overhead and margin are applied to the initial the same way they are
 * applied to the month, so the one-time number is the price that still
 * holds the target, not the raw crew cost.
 *
 * @param {object} input  Same shape as calculateBid.
 * @param {object} options
 * @param {number} [options.visitMultiplier=5] How many regular visits the
 *   initial is worth. 2–3× is a maintained building; 5× is a typical
 *   takeover of a neglected floor.
 * @param {number} [options.extraSupplies=80] Extra chemicals, liners, and
 *   dumpster cost on that first visit only.
 * @param {number} [options.amortizeMonths=12] Months over which to recover
 *   the initial if it is baked into the monthly instead of invoiced once.
 * @param {number} [options.cancelAfterMonths=1] Tenure used for the
 *   cancel-early cash comparison (default: they leave after 30 days).
 * @param {number|string|null} [options.clientOfferMonthly] Optional monthly
 *   they offered that already "includes" the initial, scored against the
 *   month-1 cost that still carries the project.
 */
export function compareInitialClean(input, options = {}) {
  const visitMultiplier = number(
    options.visitMultiplier ?? 5,
    'Initial-clean visit multiplier',
    { allowZero: false },
  );
  const extraSupplies = number(options.extraSupplies ?? 80, 'Extra initial-clean supplies');
  const amortizeMonths = number(
    options.amortizeMonths ?? 12,
    'Months to recover the initial',
    { allowZero: false },
  );
  const cancelAfterMonths = number(
    options.cancelAfterMonths ?? 1,
    'If they cancel after this many months',
    { allowZero: false },
  );
  const overheadRate = number(input.overheadRate ?? 0, 'Overhead');
  const targetMargin = number(input.targetMargin ?? 0, 'Target margin');
  if (targetMargin >= 100) throw new Error('Target margin must be less than 100%');

  const monthly = calculateBid({ ...input, proposedPrice: undefined });
  const hoursPerVisit = monthly.hoursPerVisitTotal;
  const initialHours = hoursPerVisit * visitMultiplier;
  const initialLabor = initialHours * monthly.loadedWage;
  const initialDirect = initialLabor + extraSupplies;
  const initialOverhead = initialDirect * overheadRate / 100;
  const initialCost = initialDirect + initialOverhead;
  const initialPrice = initialCost / (1 - targetMargin / 100);
  const initialProfit = initialPrice - initialCost;

  const amortizedMonthlyCost = monthly.monthlyCost + initialCost / amortizeMonths;
  const amortizedMonthlyPrice = amortizedMonthlyCost / (1 - targetMargin / 100);
  const amortizedAddOn = amortizedMonthlyPrice - monthly.monthlyPrice;

  const thrownInMonth1Cost = monthly.monthlyCost + initialCost;
  const thrownInMonth1Profit = monthly.monthlyPrice - thrownInMonth1Cost;
  const thrownInMonth1Margin = monthly.monthlyPrice === 0
    ? 0
    : thrownInMonth1Profit / monthly.monthlyPrice * 100;
  const thrownInBelowBreakEven = monthly.monthlyPrice < thrownInMonth1Cost;

  // How many months of ordinary profit equal the giveaway. Null when the
  // monthly itself does not make money — there is then no recovery path.
  const monthsOfProfitToCoverGiveaway = monthly.monthlyProfit <= 0
    ? null
    : initialCost / monthly.monthlyProfit;

  // Quoted separately they pay the one-time and the month. Thrown in they
  // pay only the month, so month 1 still carries the project cost.
  const quotedSeparatelyCashIfCancel =
    cancelAfterMonths * monthly.monthlyProfit + initialProfit;
  const thrownInCashIfCancel =
    cancelAfterMonths * monthly.monthlyProfit - initialCost;
  const giveawayVsQuotedIfCancel = thrownInCashIfCancel - quotedSeparatelyCashIfCancel;

  const hasOffer = options.clientOfferMonthly !== null
    && options.clientOfferMonthly !== undefined
    && options.clientOfferMonthly !== '';
  const offerPrice = hasOffer
    ? number(options.clientOfferMonthly, 'Monthly they offered including the initial')
    : null;
  const clientOffer = offerPrice === null ? null : {
    price: offerPrice,
    month1Profit: offerPrice - thrownInMonth1Cost,
    month1Margin: offerPrice === 0 ? 0 : (offerPrice - thrownInMonth1Cost) / offerPrice * 100,
    belowBreakEvenMonth1: offerPrice < thrownInMonth1Cost,
    laterProfit: offerPrice - monthly.monthlyCost,
    laterBelowBreakEven: offerPrice < monthly.monthlyCost,
  };

  return {
    visitMultiplier,
    extraSupplies,
    amortizeMonths,
    cancelAfterMonths,
    hoursPerVisit,
    initialHours,
    initialLabor,
    initialDirect,
    initialOverhead,
    initialCost,
    initialPrice,
    initialProfit,
    monthly,
    amortizedMonthlyCost,
    amortizedMonthlyPrice,
    amortizedAddOn,
    thrownInMonth1Cost,
    thrownInMonth1Profit,
    thrownInMonth1Margin,
    thrownInBelowBreakEven,
    monthsOfProfitToCoverGiveaway,
    quotedSeparatelyCashIfCancel,
    thrownInCashIfCancel,
    giveawayVsQuotedIfCancel,
    walkAwayMonth1: thrownInMonth1Cost,
    clientOffer,
  };
}

/**
 * One paragraph a contractor can paste into a "just include the initial"
 * reply. Arithmetic only — it does not tell them to accept or refuse.
 */
export function initialCleanNote(comparison, { targetMargin } = {}) {
  const money = (value) => {
    const format = (value) => `$${value.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    const text = format(Math.abs(value));
    return value < 0 && /[1-9]/.test(text) ? `-${text}` : text;
  };
  const marginPct = Number.isFinite(targetMargin) ? targetMargin : 20;
  const oneTime = `A ${comparison.visitMultiplier.toFixed(1)}× takeover clean (${comparison.initialHours.toFixed(1)} h plus ${money(comparison.extraSupplies)} of extra supplies) is a ${money(comparison.initialPrice)} one-time line if it still holds a ${marginPct}% margin — not a free extra on the ${money(comparison.monthly.monthlyPrice)} monthly.`;
  const thrown = comparison.thrownInBelowBreakEven
    ? `Throwing it in at today's monthly loses ${money(Math.abs(comparison.thrownInMonth1Profit))} in month 1 against a ${money(comparison.walkAwayMonth1)} walk-away.`
    : `Throwing it in at today's monthly leaves ${money(comparison.thrownInMonth1Profit)} in month 1 (${comparison.thrownInMonth1Margin.toFixed(1)}% margin), not the ${marginPct}% the monthly was built on.`;
  const amortize = `Baking it into the monthly over ${comparison.amortizeMonths} months is ${money(comparison.amortizedMonthlyPrice)} (${money(comparison.amortizedAddOn)} above today's monthly).`;
  const cancel = comparison.thrownInCashIfCancel < 0
    ? `If they cancel after ${comparison.cancelAfterMonths} month${comparison.cancelAfterMonths === 1 ? '' : 's'}, the giveaway finishes ${money(Math.abs(comparison.thrownInCashIfCancel))} under water versus ${money(comparison.quotedSeparatelyCashIfCancel)} if the initial was invoiced.`
    : `If they cancel after ${comparison.cancelAfterMonths} month${comparison.cancelAfterMonths === 1 ? '' : 's'}, throwing it in keeps ${money(comparison.thrownInCashIfCancel)} versus ${money(comparison.quotedSeparatelyCashIfCancel)} if the initial was invoiced.`;
  return [oneTime, thrown, amortize, cancel].join(' ');
}

proposal.mjs.text:
// Turns a finished bid into the document the contractor actually hands the
// customer: a one-page proposal they can print or "Save as PDF" from the
// browser.
//
// Why this exists
// ---------------
// Every bid calculator in this portfolio already ends at a number and a
// plain-text blurb to paste somewhere. That is where the tool stops and the
// contractor's evening starts: retyping the scope into Word, remembering the
// deposit split, guessing how long the price should stand. The proposal is the
// thing that wins or loses the job, and it was the one artifact none of these
// tools produced.
//
// Deliberately NOT a contract
// ---------------------------
// This renders the contractor's own words and numbers into a tidy layout. It
// invents no legal terms, warranties, lien language, or cancellation rights —
// every clause on the page is text the user typed or left blank. A "proposal"
// that shipped boilerplate terms drafted by a calculator would be exactly the
// legal exposure `PRODUCT_PLAYBOOK.md` §5b tells us to avoid, and it would be
// wrong in most jurisdictions anyway.
//
// Privacy
// -------
// `loadCompany` / `saveCompany` persist the *contractor's own* business block
// (their name, phone, licence) so they type it once. The customer's name and
// address are never persisted: that is a third party's personal data sitting on
// someone else's device, and re-typing it per job is cheap. Nothing here
// touches the network.
//
// This file is generic on purpose — no trade, no venture, no storage key baked
// in — so it can be copied verbatim into any calculator in `ventures/`. See the
// venture README for the wiring steps.

/** Fields of the contractor's own business block, in display order. */
export const COMPANY_FIELDS = Object.freeze([
  'companyName', 'companyPhone', 'companyEmail', 'companyLicense', 'companyAddress',
]);

/** Fields describing the customer and the job. Never persisted. */
export const CLIENT_FIELDS = Object.freeze([
  'clientName', 'clientAddress',
]);

/** Commercial terms the contractor controls. */
export const TERM_FIELDS = Object.freeze([
  'depositPercent', 'validDays', 'paymentTerms', 'proposalNotes', 'proposalExclusions',
]);

export function escapeHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function text(value) {
  return String(value ?? '').trim();
}

function number(value, name, { min = 0, max = Infinity } = {}) {
  const result = Number(value);
  if (!Number.isFinite(result)) throw new Error(`${name} must be a number`);
  if (result < min) throw new Error(`${name} must be at least ${min}`);
  if (result > max) throw new Error(`${name} must be at most ${max}`);
  return result;
}

/**
 * A figure for the customer's copy.
 *
 * `currency` defaults to `'$'`, which is what every trade in this portfolio
 * quotes in and what all 102 adopters rendered before it was a parameter — so
 * an unchanged caller gets a byte-identical document.
 *
 * It exists because the document is not only a US construction bid. A
 * freelancer quoting a translation names their own currency on the page, and
 * printing `$1,200.00` on a quote the client will pay in euros is not a display
 * nicety: it misstates the price on the one sheet that is meant to settle it.
 * The venture passes whatever its own currency field says.
 *
 * A label is spaced from the figure and a symbol is not — `USD 1,200.00` but
 * `$1,200.00` and `€1,200.00` — decided by whether the currency ends in a
 * letter, which is the only difference a reader would notice between the two.
 *
 * That space is a non-breaking one, written as an escape so it cannot be
 * mistaken for an ordinary space by anyone reading this file or matching
 * against its output. A quote is a printed document with a narrow price
 * column, and "USD" left stranded at the end of a line with its figure on the
 * next is the one place this layout can break in a way the customer sees.
 */
export function money(value, currency = '$') {
  // Sign goes outside the currency symbol: "-$9.24", not "$-9.24". The old
  // spelling put it inside, which is what interpolating a negative straight
  // after a "$" gets you, and it reads as a typo on a document a contractor
  // hands a customer.
  //
  // Round to cents *before* choosing the sign. A delta of two equal figures
  // lands on -0, and a residual like -0.004 rounds to zero at cent precision;
  // both used to print "$-0.00" — a line that is exactly break-even claiming
  // to be down money.
  const cents = Math.round(Math.abs(value) * 100);
  const sign = cents === 0 ? '' : value < 0 ? '-' : '';
  const amount = (cents / 100).toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
  const unit = text(currency) || '$';
  return `${sign}${unit}${/[A-Za-z]$/.test(unit) ? '\u00a0' : ''}${amount}`;
}

/**
 * Split a textarea into trimmed, non-empty lines. Blank lines are how people
 * space out a scope list; they should not become empty bullets.
 */
export function lines(value) {
  return text(value)
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean);
}

/**
 * Fill scope templates from a calculator's result, dropping any line whose
 * figures are not there.
 *
 * Every adoption batch so far has lost a line to the same defect: each
 * calculator names its result differently, `result.doorClass` or `run.material`
 * resolves to `undefined` rather than throwing, and the customer's scope reads
 * "undefined ft of undefined" while every suite stays green. Guessing is the
 * problem; this makes guessing wrong *visible* instead of silent.
 *
 * A template is `'Install {totalLinearFeet} ft of {fenceName}'`, or an object
 * `{ line, when }` where `when` names a field that must be truthy for the line
 * to appear at all.
 *
 * `{ each, line, when }` renders one line **per element** of the array at
 * `each`, with `{field}` reading that element rather than the result root.
 * Half the calculators here price an itemised job — rooms of flooring, gutter
 * runs, trees, kitchen exhaust components — and a homeowner collecting three
 * bids compares the line items, not a total. Without this the only scope such
 * a trade could draft is "Perform the work described above", which the README
 * is explicit is worth less than no proposal at all. `when` is read against
 * the element too, so a row the contractor left at zero stays off the quote:
 *
 * ```json
 * { "each": "rooms", "when": "hours", "line": "{name} — {squareFeet~0} sq ft" }
 * ```
 *
 * Elements are not truncated. Every row the contractor entered is a row they
 * intend to be paid for, and "…and 4 more" on a document someone signs is a
 * dispute waiting to happen.
 *
 * `{field+s}` is that field's plural suffix — `'s'` unless the value is exactly
 * one — so `'{gates} gate{gates+s}'` reads "1 gate" and "3 gates". Without it
 * the obvious thing to write is `'{gates} gate{gates}'`, which prints
 * "3 gate3" on a customer's quote.
 *
 * `{field~2}` rounds to that many decimals and groups thousands, so a derived
 * figure reads "48.89 yd²" and "1,600 sq ft" rather than "48.888888888888886"
 * and "1600". Anything computed — a yardage, a tonnage, a square count — needs
 * it: a quote carrying fifteen decimal places tells the customer the number was
 * produced by a machine that was not being watched.
 *
 * A placeholder that resolves to `undefined`, `null`, `''`,
 * `NaN`, or `Infinity` drops its whole line — a scope with one line missing is
 * a scope the contractor edits, whereas a scope reading `undefined` is one they
 * hand to a customer without noticing.
 *
 * Dropping is not the safety property on its own: an empty scope is also wrong,
 * and `platform/proposal/verify.mjs` fails a page whose default scope comes out
 * empty. Between them, a mis-named field cannot reach a customer quietly.
 *
 * @param {Array<string|{line: string, when?: string, each?: string}>} templates
 * @param {object} values The calculator's result (and anything else to read).
 * @returns {string[]}
 */
export function scopeLines(templates, values) {
  const missing = (value) => value === undefined || value === null || value === ''
    || (typeof value === 'number' && !Number.isFinite(value));

  const readFrom = (scope, path) => String(path).split('.')
    .reduce((node, key) => (node === null || node === undefined ? undefined : node[key]), scope);

  /**
   * One template line against one scope, or `null` if any placeholder in it is
   * missing. Shared by plain lines and `each` rows on purpose: a row must drop
   * on a missing figure by exactly the same rule as a top-level line, or the
   * word "undefined" reaches the customer through whichever path was written
   * second.
   */
  const render = (line, scope) => {
    let complete = true;
    const rendered = line.replace(
      /\{([A-Za-z0-9_.]+?)(?:\+([A-Za-z]+)|~(\d))?\}/g,
      (_match, path, plural, decimals) => {
        const value = readFrom(scope, path);
        if (missing(value)) { complete = false; return ''; }
        if (plural !== undefined) return Number(value) === 1 ? '' : plural;
        if (decimals !== undefined) {
          const number = Number(value);
          if (!Number.isFinite(number)) { complete = false; return ''; }
          return number.toLocaleString('en-US', {
            minimumFractionDigits: 0,
            maximumFractionDigits: Number(decimals),
          });
        }
        return String(value);
      },
    );
    return complete && rendered.trim() ? rendered.trim() : null;
  };

  const filled = [];
  for (const template of templates ?? []) {
    const line = typeof template === 'string' ? template : template?.line;
    if (typeof line !== 'string') continue;
    const each = typeof template === 'object' ? template.each : undefined;

    if (each !== undefined) {
      const rows = readFrom(values, each);
      if (!Array.isArray(rows)) continue;
      for (const row of rows) {
        if (row === null || typeof row !== 'object') continue;
        if (template.when !== undefined && !readFrom(row, template.when)) continue;
        const rendered = render(line, row);
        if (rendered !== null) filled.push(rendered);
      }
      continue;
    }

    if (typeof template === 'object' && template.when !== undefined && !readFrom(values, template.when)) continue;
    const rendered = render(line, values);
    if (rendered !== null) filled.push(rendered);
  }
  return filled;
}

/**
 * `YYYY-MM-DD` plus a whole number of days, in UTC.
 *
 * Local-time date arithmetic silently shifts by a day across a DST boundary,
 * which on a quote-expiry date is a real dispute with a customer.
 */
export function addDays(isoDate, days) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text(isoDate));
  if (!match) throw new Error('Issue date must be YYYY-MM-DD');
  const [, year, month, day] = match;
  const stamp = Date.UTC(Number(year), Number(month) - 1, Number(day));
  if (Number.isNaN(stamp)) throw new Error('Issue date must be a real date');
  return new Date(stamp + number(days, 'Valid days') * 86_400_000)
    .toISOString()
    .slice(0, 10);
}

/** `2026-08-26` → `26 August 2026`. Unambiguous to both US and non-US readers. */
export function formatDate(isoDate) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text(isoDate));
  if (!match) return text(isoDate);
  const [, year, month, day] = match;
  const monthName = new Date(Date.UTC(Number(year), Number(month) - 1, 1))
    .toLocaleDateString('en-US', { month: 'long', timeZone: 'UTC' });
  return `${Number(day)} ${monthName} ${year}`;
}

/**
 * A short, stable reference the contractor and the customer can both quote on
 * the phone. Derived from the issue date and the customer name so that
 * re-printing the same proposal gives the same number, and two proposals
 * written the same day for different customers do not collide.
 */
export function referenceFor(issuedOn, clientName) {
  const compact = text(issuedOn).replaceAll('-', '');
  let hash = 0;
  for (const character of text(clientName).toUpperCase()) {
    hash = (hash * 31 + character.codePointAt(0)) % 1_048_576;
  }
  return `Q-${compact}-${hash.toString(36).toUpperCase().padStart(4, '0').slice(-4)}`;
}

/**
 * Assemble and validate a proposal.
 *
 * Throws on the things that would embarrass the contractor in front of a
 * customer — no business name, no customer name, a zero price, a deposit over
 * 100% — rather than rendering a document with a hole in it.
 */
export function buildProposal(input = {}) {
  const companyName = text(input.companyName);
  if (!companyName) throw new Error('Add your business name before printing a proposal');
  const clientName = text(input.clientName);
  if (!clientName) throw new Error('Add the customer name before printing a proposal');

  const price = number(input.price, 'Price', { min: 0 });
  if (price <= 0) throw new Error('Price a job before printing a proposal');

  const depositPercent = number(input.depositPercent ?? 0, 'Deposit', { min: 0, max: 100 });
  const validDays = number(input.validDays ?? 0, 'Valid days', { min: 0, max: 3650 });
  const issuedOn = text(input.issuedOn) || new Date().toISOString().slice(0, 10);

  // Rounded to cents here, not at display time, and the balance taken as the
  // remainder. The customer adds the two lines up: if the deposit rounds up and
  // the balance rounds down independently, the printed figures miss the printed
  // total by a cent, and the contractor has to explain it on the phone.
  const depositAmount = Math.round(price * depositPercent) / 100;

  return {
    reference: referenceFor(issuedOn, clientName),
    issuedOn,
    validDays,
    validUntil: validDays === 0 ? null : addDays(issuedOn, validDays),
    company: {
      name: companyName,
      phone: text(input.companyPhone),
      email: text(input.companyEmail),
      license: text(input.companyLicense),
      address: text(input.companyAddress),
    },
    client: {
      name: clientName,
      address: text(input.clientAddress),
    },
    job: {
      title: text(input.jobTitle) || 'Proposed work',
      scope: lines(input.scope),
      exclusions: lines(input.proposalExclusions),
      notes: text(input.proposalNotes),
    },
    pricing: {
      price,
      depositPercent,
      depositAmount,
      balanceAmount: price - depositAmount,
      paymentTerms: text(input.paymentTerms),
    },
  };
}

function block(title, body) {
  return body ? `<div class="pr-block"><h3>${escapeHtml(title)}</h3>${body}</div>` : '';
}

function list(items) {
  return items.length === 0
    ? ''
    : `<ul>${items.map((item) => `<li>${escapeHtml(item)}</li>`).join('')}</ul>`;
}

function paragraphs(value) {
  return value ? `<p>${escapeHtml(value).replaceAll('\n', '<br>')}</p>` : '';
}

/**
 * Render the proposal as the HTML that goes inside the page's print container.
 *
 * Returns a fragment, not a whole document: the page owns the print stylesheet,
 * so the same markup is what the contractor previews on screen and what comes
 * out of the printer. A separate print-only document is how the two drift.
 *
 * @param {ReturnType<typeof buildProposal>} proposal
 * @param {object} [options]
 * @param {string} [options.disclaimer] Sentence to print in the footer. The
 *   caller supplies it so each trade can name its own regulator and scope.
 * @param {string} [options.currency] Prefix for every figure on the sheet.
 *   Defaults to `'$'`; see `money`.
 */
export function renderProposalHtml(proposal, { disclaimer = '', currency = '$' } = {}) {
  const { company, client, job, pricing } = proposal;
  const amount = (value) => money(value, currency);

  const contact = [company.phone, company.email, company.address]
    .filter(Boolean)
    .map((line) => `<span>${escapeHtml(line)}</span>`)
    .join('');

  const validity = proposal.validUntil
    ? `<p class="pr-validity">This price is held until <strong>${escapeHtml(formatDate(proposal.validUntil))}</strong> (${proposal.validDays} days from issue).</p>`
    : '';

  const depositRow = pricing.depositPercent > 0
    ? `<tr><td>Deposit due on acceptance (${pricing.depositPercent}%)</td><td>${amount(pricing.depositAmount)}</td></tr>
       <tr><td>Balance due on completion</td><td>${amount(pricing.balanceAmount)}</td></tr>`
    : '';

  return `
    <article class="pr-doc">
      <header class="pr-head">
        <div>
          <h2>${escapeHtml(company.name)}</h2>
          <div class="pr-contact">${contact}</div>
          ${company.license ? `<p class="pr-license">Licence ${escapeHtml(company.license)}</p>` : ''}
        </div>
        <div class="pr-meta">
          <p class="pr-kicker">Proposal</p>
          <p><strong>${escapeHtml(proposal.reference)}</strong></p>
          <p>${escapeHtml(formatDate(proposal.issuedOn))}</p>
        </div>
      </header>

      <div class="pr-parties">
        <div class="pr-block"><h3>Prepared for</h3>
          <p><strong>${escapeHtml(client.name)}</strong></p>
          ${paragraphs(client.address)}
        </div>
        <div class="pr-block"><h3>Work</h3>
          <p><strong>${escapeHtml(job.title)}</strong></p>
        </div>
      </div>

      ${block('Scope of work', list(job.scope))}
      ${block('Not included', list(job.exclusions))}
      ${block('Notes', paragraphs(job.notes))}

      <table class="pr-price">
        <tbody>
          <tr class="pr-total"><td>Total price</td><td>${amount(pricing.price)}</td></tr>
          ${depositRow}
        </tbody>
      </table>
      ${validity}
      ${block('Payment terms', paragraphs(pricing.paymentTerms))}

      <div class="pr-sign">
        <div><span class="pr-rule"></span><p>Customer signature</p></div>
        <div><span class="pr-rule"></span><p>Date</p></div>
      </div>

      ${disclaimer ? `<p class="pr-disclaimer">${escapeHtml(disclaimer)}</p>` : ''}
    </article>
  `;
}

/**
 * Read the saved business block. A corrupt or absent entry is an empty block,
 * never an exception: a broken localStorage value must not stop someone
 * pricing a job.
 */
export function loadCompany(storage, key) {
  try {
    const saved = JSON.parse(storage?.getItem(key) || '{}');
    return Object.fromEntries(
      COMPANY_FIELDS.map((field) => [field, text(saved?.[field])]),
    );
  } catch {
    return Object.fromEntries(COMPANY_FIELDS.map((field) => [field, '']));
  }
}

/**
 * Persist the business block only. `CLIENT_FIELDS` are excluded by
 * construction, not by the caller remembering to strip them.
 */
export function saveCompany(storage, key, values = {}) {
  const payload = Object.fromEntries(
    COMPANY_FIELDS.map((field) => [field, text(values[field])]),
  );
  try {
    storage?.setItem(key, JSON.stringify(payload));
  } catch {
    // A full or disabled localStorage is not worth an error in front of the
    // customer; the proposal still prints, it just will not be pre-filled next
    // time.
  }
  return payload;
}

export function forgetCompany(storage, key) {
  try {
    storage?.removeItem(key);
  } catch {
    // Same reasoning as saveCompany.
  }
}

second-site.mjs.text:
// Incremental cost of taking a second building after the drive.
//
// The first-building bid in calc.mjs prices one site. Contractors lose money
// on the second by quoting that same production-rate price and treating the
// van as free. Drive time is loaded labor, not windshield scenery, and the
// extra fuel/wear is a monthly direct cost. Both take overhead the same way
// the first building's chemicals do.
//
// This module does not change calculateBid. Frequency-cut, day-porter, and
// strip-and-wax work stay on those branches; this only answers "does the
// next address still pay once we count the minutes between them?"

import { calculateBid, WEEKS_PER_MONTH } from './calc.mjs';

function number(value, name, { min = 0, allowZero = true } = {}) {
  const result = Number(value);
  if (!Number.isFinite(result)) throw new Error(`${name} must be a number`);
  if (result < min) throw new Error(`${name} must be at least ${min}`);
  if (!allowZero && result === 0) throw new Error(`${name} must be greater than zero`);
  return result;
}

/**
 * Price a second site including the drive from the current route.
 *
 * @param {object} input
 * @param {object} input.candidate          Same shape as calculateBid for the
 *   new building only. Do not re-enter the first site's truck here — that
 *   cost is already on the book. Put only incremental equipment on the
 *   candidate, plus extraVehicleMonthly for fuel and wear.
 * @param {number} input.driveMinutesOneWay Minutes from the current route
 *   (home or the first building) to the new site, one way.
 * @param {number} input.tripsPerWeek       How many times the crew actually
 *   drives there. Usually the new site's cleanings per week; less if they
 *   stack two buildings on the same night.
 * @param {number} input.extraVehicleMonthly Incremental fuel, tolls, and
 *   wear beyond the first site's vehicle line.
 * @param {number|string|null} [input.offeredMonthly] Optional price the
 *   prospect put on the new site, scored against the drive-inclusive cost.
 * @param {number|string|null} [input.existingMonthlyProfit] Optional profit
 *   already kept on the first building, so the combined book is visible.
 */
export function compareSecondSite(input) {
  const driveMinutesOneWay = number(input.driveMinutesOneWay ?? 0, 'Drive minutes one way');
  const tripsPerWeek = number(input.tripsPerWeek ?? 0, 'Trips per week');
  const extraVehicleMonthly = number(input.extraVehicleMonthly ?? 0, 'Extra vehicle cost');
  const overheadRate = number(input.candidate?.overheadRate ?? 0, 'Overhead');
  const targetMargin = number(input.candidate?.targetMargin ?? 0, 'Target margin');
  if (targetMargin >= 100) throw new Error('Target margin must be less than 100%');

  const building = calculateBid({ ...input.candidate, proposedPrice: undefined });

  // Round trip, then weeks-per-month — the same conversion the first-building
  // bid uses, so a 25-minute hop three nights a week is not "about an hour."
  const monthlyDriveHours = (driveMinutesOneWay * 2 / 60) * tripsPerWeek * WEEKS_PER_MONTH;
  const monthlyDriveLabor = monthlyDriveHours * building.loadedWage;
  const addedDirect = monthlyDriveLabor + extraVehicleMonthly;
  const addedOverhead = addedDirect * overheadRate / 100;
  const incrementalCost = building.monthlyCost + addedDirect + addedOverhead;
  const priceToHoldMargin = incrementalCost / (1 - targetMargin / 100);
  const ignoredDrivePrice = building.monthlyPrice;
  const driveGap = priceToHoldMargin - ignoredDrivePrice;

  const serviceHours = building.monthlyHours + monthlyDriveHours;
  const driveShare = serviceHours === 0 ? 0 : monthlyDriveHours / serviceHours * 100;

  const hasOffer = input.offeredMonthly !== null && input.offeredMonthly !== undefined && input.offeredMonthly !== '';
  const offeredMonthly = hasOffer ? number(input.offeredMonthly, 'Offered monthly price') : null;
  const offeredProfit = offeredMonthly === null ? null : offeredMonthly - incrementalCost;
  const offeredMargin = offeredMonthly === null || offeredMonthly === 0
    ? null
    : offeredProfit / offeredMonthly * 100;

  const hasExisting = input.existingMonthlyProfit !== null
    && input.existingMonthlyProfit !== undefined
    && input.existingMonthlyProfit !== '';
  const existingMonthlyProfit = hasExisting
    ? number(input.existingMonthlyProfit, 'Existing monthly profit')
    : null;

  return {
    building,
    driveMinutesOneWay,
    tripsPerWeek,
    extraVehicleMonthly,
    monthlyDriveHours,
    monthlyDriveLabor,
    addedDirect,
    addedOverhead,
    incrementalCost,
    priceToHoldMargin,
    incrementalProfitAtTarget: priceToHoldMargin - incrementalCost,
    ignoredDrivePrice,
    driveGap,
    serviceHours,
    driveShare,
    walkAwayMonthly: incrementalCost,
    offered: offeredMonthly === null ? null : {
      price: offeredMonthly,
      profit: offeredProfit,
      margin: offeredMargin,
      belowWalkAway: offeredMonthly < incrementalCost,
      missesTarget: offeredMonthly < priceToHoldMargin,
    },
    existingMonthlyProfit,
    combinedProfitAtOffer: existingMonthlyProfit === null || offeredProfit === null
      ? null
      : existingMonthlyProfit + offeredProfit,
    combinedProfitAtTarget: existingMonthlyProfit === null
      ? null
      : existingMonthlyProfit + (priceToHoldMargin - incrementalCost),
  };
}

/**
 * One paragraph a contractor can paste into a bid or a "thanks, here's why
 * the number is not the same as the first building" reply. Arithmetic only.
 */
export function secondSiteNote(comparison, { targetMargin } = {}) {
  const money = (value) => {
    const format = (value) => `$${value.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    const text = format(Math.abs(value));
    return value < 0 && /[1-9]/.test(text) ? `-${text}` : text;
  };
  const marginLabel = Number.isFinite(targetMargin) ? targetMargin : 20;
  const driveLine = comparison.monthlyDriveHours === 0
    ? 'No drive time is included in this figure.'
    : `${comparison.monthlyDriveHours.toFixed(1)} labor hours a month are on the road (${comparison.driveShare.toFixed(0)}% of the hours this site needs), at the same loaded wage as the clean.`;
  const offerLine = comparison.offered === null
    ? `The walk-away on this site, drive included, is ${money(comparison.walkAwayMonthly)}.`
    : comparison.offered.belowWalkAway
      ? `At ${money(comparison.offered.price)} this site loses ${money(Math.abs(comparison.offered.profit))} a month after the drive. Walk-away is ${money(comparison.walkAwayMonthly)}.`
      : comparison.offered.missesTarget
        ? `At ${money(comparison.offered.price)} this site covers cost after the drive but leaves a ${(comparison.offered.margin ?? 0).toFixed(1)}% margin — ${money(comparison.priceToHoldMargin - comparison.offered.price)} a month short of a ${marginLabel}% target.`
        : `At ${money(comparison.offered.price)} this site still holds a ${(comparison.offered.margin ?? 0).toFixed(1)}% margin after the drive.`;
  return [
    `The price that still holds a ${marginLabel}% margin on the second building, including the drive, is ${money(comparison.priceToHoldMargin)} — not the ${money(comparison.ignoredDrivePrice)} you would quote if the van were free.`,
    driveLine,
    offerLine,
  ].join(' ');
}

share.mjs.text:
// A setter re-enters the same wage, burden, overhead, markup, and material
// rates on every single bid. Losing them when the tab closes is the reason a
// pricing tool gets used once and never again, so this module keeps the whole
// form: to the visitor's own browser between visits, and into a link they can
// send themselves, a partner, or the customer.
//
// The transform is pure and takes the field spec as an argument rather than
// keeping its own copy of the field list. That is deliberate. `index.html`
// already declares the ids `readInput()` reads, so passing those same arrays
// in means a field added to the form is shareable the moment it exists. A
// second hand-maintained allowlist in here would silently drop whatever the
// form grew since — a shared link that computes a different price than the
// sender saw is worse than no link at all.
//
// Nothing here is transmitted. `localStorage` is the visitor's own disk, and
// the link is only ever built in their browser and copied by them. The bid
// travels in the URL *fragment* (`#...`), never the query string: a fragment
// is not sent in the request line a server logs, nor in the `Referer` header a
// later click would carry, so the numbers a setter typed stay on the machines
// they choose to send the link to. `encodeBid` returns a bare parameter string
// and `decodeBid` accepts it with or without a leading `#`, so this module
// stays agnostic to which the caller uses; the calculators use the fragment.

// Spec shape, built by the caller from its existing id lists:
//   {
//     key:     'kitchen-tile-backsplash-bid',   // localStorage key
//     numbers: ['wallSf', 'hourlyWage', ...],   // free numeric inputs
//     flags:   ['includeCooktop', ...],         // checkboxes
//     choices: { scope: ['tile-only', ...] },   // selects, with their options
//     text:    ['paymentTerms', ...],           // free prose (textarea)
//     rows:    { param: 'a', fields: [...] },   // optional repeated group
//   }
//
// `rows` is for a form whose shape the visitor sets — the janitorial bid is a
// list of spaces in a building, and there is no fixed field list to name. It
// is the case that most needs keeping: re-measuring a building to re-price it
// is an hour of work, not a retyped wage. Each row encodes as colon-separated
// values in spec order, rows separated by commas, under one parameter.

const VERSION = 1;
const ROW_SEPARATOR = ',';
const CELL_SEPARATOR = ':';
// A form the visitor grows without limit is a form a crafted link can grow
// without limit too. This is far above any real building and far below what
// would take a browser down.
const MAX_ROWS = 200;

// Only a finite, non-negative number is carried. That is the same contract the
// calculators enforce on input, so a restored or shared value can never
// prefill a field the calculator would then reject.
function usableNumber(value) {
  if (value === '' || value === null || value === undefined) return null;
  const result = Number(value);
  if (!Number.isFinite(result) || result < 0) return null;
  return result;
}

function specNumbers(spec) {
  return Array.isArray(spec?.numbers) ? spec.numbers : [];
}

function specFlags(spec) {
  return Array.isArray(spec?.flags) ? spec.flags : [];
}

function specChoices(spec) {
  return spec?.choices && typeof spec.choices === 'object' ? spec.choices : {};
}

function specText(spec) {
  return Array.isArray(spec?.text) ? spec.text : [];
}

// The proposal panel's terms — see `withProposalTerms`. Two numbers and three
// blocks of prose, named here rather than in the page because the page's copy
// of the list is generated by `platform/proposal/adopt.mjs` and a second
// hand-kept copy beside it is the exact defect this module's header warns
// about. `platform/proposal/term-ids.test.mjs` asserts the two agree.
export const PROPOSAL_TERM_NUMBERS = Object.freeze(['depositPercent', 'validDays']);
export const PROPOSAL_TERM_TEXT = Object.freeze([
  'proposalExclusions', 'paymentTerms', 'proposalNotes',
]);

// A ceiling on one block of prose, matching `MAX_LINK_VALUE` in
// `platform/pages/link.mjs` so the two share mechanisms on this site agree
// about what fits in a fragment. Payment terms and exclusions are a sentence or
// two in every real bid; a field past this is a document, and a URL is not
// where a document travels.
export const MAX_TERM_TEXT = 512;

// Prose is carried as typed, newlines included — these are textareas and a
// three-line exclusions list is three lines on the customer's sheet. Only two
// things are taken out: the control characters no textarea produces and no
// proposal should render, and the surrounding whitespace, so a field holding
// only a stray newline reads as empty rather than as terms the sender wrote.
//
// Over-long is `null` — dropped, not truncated. Half a payment-terms clause,
// presented to the recipient as the sender's terms, is worse than the field
// arriving empty, and `overlongTerms` is what lets the sender be told which one
// stayed behind instead of finding out from the customer.
function usableText(value) {
  if (typeof value !== 'string') return null;
  // eslint-disable-next-line no-control-regex
  const clean = value.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '').trim();
  if (!clean) return null;
  return clean.length > MAX_TERM_TEXT ? null : clean;
}

/**
 * The spec, plus the proposal terms this page also puts in front of the setter.
 *
 * Why this is not simply written into each venture's spec: the terms are not
 * the venture's fields. They arrive with the proposal panel that
 * `platform/proposal/adopt.mjs` generates into the page, below the pricing form
 * and after the spec is built, so a page cannot name them in its own
 * `numbers`/`text` arrays without restating a list it does not own.
 *
 * The defect this fixes is small on screen and expensive on paper. A setter
 * prices a job at a 50% deposit held for 15 days, sends the link, and the
 * recipient's page opens the *bid* correctly under this venture's defaults —
 * 30% and 30 days. Both people are looking at the same price and different
 * money on acceptance, and nothing anywhere says so. The same was true of the
 * setter's own saved bid on their next visit.
 *
 * Idempotent: folding the terms in twice leaves one copy, so a caller that
 * wraps at every call site (which is what the pages do) cannot grow the spec.
 */
export function withProposalTerms(spec) {
  if (!spec || typeof spec !== 'object') return spec;
  const numbers = specNumbers(spec);
  const text = specText(spec);
  return {
    ...spec,
    numbers: [...numbers, ...PROPOSAL_TERM_NUMBERS.filter((id) => !numbers.includes(id))],
    text: [...text, ...PROPOSAL_TERM_TEXT.filter((id) => !text.includes(id))],
  };
}

/**
 * The form's values, plus whichever term fields this page actually has.
 *
 * `lookup` is the page's own `el` — id to element, or null. Kept as an argument
 * rather than reaching for `document` so this module stays testable without a
 * DOM, which is the whole reason the transform above is pure.
 *
 * A page that has not adopted the proposal panel has no such elements and gets
 * its values back unchanged, so the same call site is correct on every venture
 * whether or not the terms are there.
 */
export function readProposalTerms(values, lookup) {
  const out = { ...(values || {}) };
  if (typeof lookup !== 'function') return out;
  for (const id of [...PROPOSAL_TERM_NUMBERS, ...PROPOSAL_TERM_TEXT]) {
    let field = null;
    try {
      field = lookup(id);
    } catch {
      // `el` throws on some pages when the id is absent. Absent is the answer.
    }
    if (field && typeof field.value === 'string') out[id] = field.value;
  }
  return out;
}

/**
 * Which term fields are too long to ride in a link.
 *
 * Named for the sender at the moment they copy, for the reason
 * `platform/pages/link.mjs` learned on `security-camera-bid-calculator`: a
 * field the encoder set aside silently is a field the recipient reads as one
 * the sender left blank.
 */
export function overlongTerms(values) {
  return PROPOSAL_TERM_TEXT.filter((id) => {
    const raw = values?.[id];
    return typeof raw === 'string' && raw.trim().length > MAX_TERM_TEXT;
  });
}

// What the setter calls these fields. The label on the panel, not the id: a
// status line reading "your proposalExclusions is too long" tells a contractor
// nothing about which box on their screen to shorten.
const TERM_LABELS = Object.freeze({
  proposalExclusions: 'not-included list',
  paymentTerms: 'payment terms',
  proposalNotes: 'notes',
});

/**
 * The sentence a page shows when a term did not fit, or `''` when all of them
 * did.
 *
 * Assembled here rather than in each page for the reason the ids are named
 * here: this wording ships on every calculator that has adopted the proposal,
 * and the alternative is the same sentence written 36 times and corrected in
 * one of them.
 */
export function overlongTermsNote(values) {
  const left = overlongTerms(values).map((id) => TERM_LABELS[id] ?? id);
  if (left.length === 0) return '';
  const named = left.length === 1
    ? left[0]
    : `${left.slice(0, -1).join(', ')} and ${left[left.length - 1]}`;
  return `your ${named} ${left.length === 1 ? 'is' : 'are'} too long to fit in a link `
    + `and stayed behind — send ${left.length === 1 ? 'it' : 'them'} separately if the wording matters`;
}

// A select's value is a string in the DOM, so this used to test `typeof value
// === 'string'` and be done. A page is free to coerce it before handing the
// values here, and one does: `sewer-line-replace-bid-calculator` runs
// `values.diameterIn = Number(values.diameterIn)` in `readInput()` so its own
// arithmetic gets a number. The strict check then dropped `diameterIn` from
// the link *and* from the save, with nothing said — a bid priced for a 6-inch
// lateral reopened as a 4-inch one, for the recipient and for the setter's own
// next visit, and the price moved with it.
//
// So the comparison is made on the string form. The allowed list is still what
// decides: a number that is not an option the select offers is rejected exactly
// as a string that is not. Only a string or a finite number gets that far —
// `true` must not slip in as the option `"true"`, and an object must not
// arrive as `"[object Object]"`.
function choiceText(value) {
  if (typeof value === 'string') return value;
  if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  return null;
}

// values object -> query string (no leading '?'). Field order follows the
// spec, so the same bid always encodes to the same string and a copied link
// stays stable across visits.
export function encodeBid(spec, values) {
  const params = new URLSearchParams();
  const choices = specChoices(spec);
  for (const [id, allowed] of Object.entries(choices)) {
    const value = choiceText(values?.[id]);
    if (value !== null && allowed.includes(value)) params.set(id, value);
  }
  for (const id of specNumbers(spec)) {
    const value = usableNumber(values?.[id]);
    if (value !== null) params.set(id, String(value));
  }
  for (const id of specFlags(spec)) {
    if (values?.[id] === undefined) continue;
    params.set(id, values[id] ? '1' : '0');
  }
  for (const id of specText(spec)) {
    const value = usableText(values?.[id]);
    if (value !== null) params.set(id, value);
  }
  for (const rows of specRowGroups(spec)) {
    if (!Array.isArray(values?.[rows.param])) continue;
    const encoded = values[rows.param]
      .slice(0, MAX_ROWS)
      .map(row => rows.fields.map(field => encodeCell(field, row?.[field.key])).join(CELL_SEPARATOR))
      // A row where every cell was rejected carries nothing; emitting it would
      // give the recipient a blank space to puzzle over.
      .filter(row => row.replaceAll(CELL_SEPARATOR, '') !== '');
    if (encoded.length > 0) params.set(rows.param, encoded.join(ROW_SEPARATOR));
  }
  return params.toString();
}

function specRows(spec) {
  const rows = spec?.rows;
  if (!rows || typeof rows.param !== 'string' || !Array.isArray(rows.fields)) return null;
  return rows;
}

function specRowGroups(spec) {
  const groups = [];
  const primary = specRows(spec);
  if (primary) groups.push(primary);
  if (Array.isArray(spec?.extraRows)) {
    for (const rows of spec.extraRows) {
      if (rows && typeof rows.param === 'string' && Array.isArray(rows.fields)) {
        groups.push(rows);
      }
    }
  }
  return groups;
}

const MAX_TEXT = 80;

function encodeText(value) {
  const raw = String(value ?? '').trim().slice(0, MAX_TEXT);
  if (!raw) return '';
  // URI-encode so a typed name can contain ":" or "," without splitting the row.
  return encodeURIComponent(raw);
}

function decodeText(raw) {
  if (!raw) return null;
  try {
    const text = decodeURIComponent(raw).trim().slice(0, MAX_TEXT);
    return text || null;
  } catch {
    return null;
  }
}

function encodeCell(field, value) {
  if (field.kind === 'choice') {
    // Same coercion tolerance as `encodeBid` above, for the same reason: a row
    // cell is read out of a form the visitor grew, and a page that normalises
    // it on the way in should not lose it on the way out.
    const text = choiceText(value);
    return text !== null && field.options.includes(text) ? text : '';
  }
  if (field.kind === 'text') return encodeText(value);
  const number = usableNumber(value);
  return number === null ? '' : String(number);
}

function decodeCell(field, raw) {
  if (field.kind === 'choice') return field.options.includes(raw) ? raw : null;
  if (field.kind === 'text') return decodeText(raw);
  const number = usableNumber(raw);
  return number === null ? null : String(number);
}

// query string -> values object. Accepts a bare query string or one with a
// leading '?' or '#', so a caller can hand it `location.search` untouched.
// Only ids named in the spec survive, numbers must parse, and a select only
// takes a value the select actually offers — a crafted link cannot inject a
// scope the calculator has no rates for, or any markup at all.
export function decodeBid(spec, source) {
  if (typeof source !== 'string') return {};
  const params = new URLSearchParams(source.replace(/^[?#]/, ''));
  const values = {};
  for (const [id, allowed] of Object.entries(specChoices(spec))) {
    if (!params.has(id)) continue;
    const value = params.get(id);
    if (allowed.includes(value)) values[id] = value;
  }
  for (const id of specNumbers(spec)) {
    if (!params.has(id)) continue;
    const value = usableNumber(params.get(id));
    if (value !== null) values[id] = String(value);
  }
  for (const id of specFlags(spec)) {
    if (!params.has(id)) continue;
    values[id] = params.get(id) === '1';
  }
  // Re-validated on the way in exactly as on the way out, because the fragment
  // is the one part of this page a stranger can write. A crafted link cannot
  // paste a megabyte of prose, or a control character, into a document the
  // contractor is about to print for a customer.
  for (const id of specText(spec)) {
    if (!params.has(id)) continue;
    const value = usableText(params.get(id));
    if (value !== null) values[id] = value;
  }
  for (const rows of specRowGroups(spec)) {
    if (!params.has(rows.param)) continue;
    const decoded = params.get(rows.param)
      .split(ROW_SEPARATOR)
      .slice(0, MAX_ROWS)
      .map(row => {
        const cells = row.split(CELL_SEPARATOR);
        const out = {};
        rows.fields.forEach((field, index) => {
          const value = decodeCell(field, cells[index] ?? '');
          if (value !== null) out[field.key] = value;
        });
        return out;
      })
      // A row that survived validation with nothing in it is not a space the
      // sender described, so it is dropped rather than added to the form.
      .filter(row => Object.keys(row).length > 0);
    if (decoded.length > 0) values[rows.param] = decoded;
  }
  return values;
}

// Writes the bid to the visitor's own storage. Wrapped because a browser with
// site data blocked throws on access rather than returning null, and a setter
// mid-bid should not lose the page over a storage setting.
export function saveBid(storage, spec, values) {
  if (!storage || !spec?.key) return false;
  try {
    storage.setItem(spec.key, JSON.stringify({ v: VERSION, values: decodeBid(spec, encodeBid(spec, values)) }));
    return true;
  } catch {
    return false;
  }
}

// Reads a previously saved bid back, re-validated through the same spec so a
// stored blob edited by hand, or written by an older version of the form, can
// only ever produce fields this build knows about.
export function loadBid(storage, spec) {
  if (!storage || !spec?.key) return {};
  try {
    const raw = storage.getItem(spec.key);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    if (!parsed || parsed.v !== VERSION || typeof parsed.values !== 'object') return {};
    return decodeBid(spec, encodeBid(spec, parsed.values));
  } catch {
    return {};
  }
}

export function clearBid(storage, spec) {
  if (!storage || !spec?.key) return false;
  try {
    storage.removeItem(spec.key);
    return true;
  } catch {
    return false;
  }
}

// A link wins over storage: a setter who opens a bid someone sent them means
// to see that bid, not the one they last priced. Storage is the fallback for a
// plain visit. Returns the values plus which source answered, so the page can
// say so rather than silently changing numbers under the visitor.
export function restoreBid(spec, { search = '', storage = null } = {}) {
  const fromLink = decodeBid(spec, search);
  if (Object.keys(fromLink).length > 0) return { values: fromLink, source: 'link' };
  const stored = loadBid(storage, spec);
  if (Object.keys(stored).length > 0) return { values: stored, source: 'storage' };
  return { values: {}, source: 'none' };
}

